DELETE FROM orders_clean; DELETE FROM orders_rejected;
INSERT INTO orders_rejected SELECT raw_id,order_id,'exact_duplicate',raw_json FROM(SELECT r.*,row_number() OVER(PARTITION BY row_hash ORDER BY raw_id) n FROM orders_raw r) WHERE n>1;
INSERT OR IGNORE INTO orders_rejected SELECT raw_id,order_id,CASE WHEN qty<=0 THEN 'non_positive_quantity' WHEN unit_price<=0 THEN 'non_positive_unit_price' WHEN unit_price>=100000 THEN 'sentinel_unit_price' ELSE 'unrecoverable_customer_id' END,raw_json FROM orders_raw WHERE qty<=0 OR unit_price<=0 OR unit_price>=100000 OR(customer_id IS NULL AND customer_email NOT LIKE 'customer%@example.com');
WITH n AS(SELECT r.*,CASE sku WHEN 'SKUEL001' THEN 'SKU-EL-001' WHEN 'SKU HK 003' THEN 'SKU-HK-003' WHEN 'SKU-FA-O03' THEN 'SKU-FA-003' ELSE upper(trim(sku)) END clean_sku,CASE WHEN order_ts NOT GLOB '*[^0-9]*' AND length(order_ts) IN(10,13) THEN datetime(CAST(substr(order_ts,1,10) AS INTEGER),'unixepoch') ELSE datetime(order_ts) END clean_ts,row_number() OVER(PARTITION BY row_hash ORDER BY raw_id) copy FROM orders_raw r),v AS(SELECT *,coalesce(customer_id,CAST(substr(lower(trim(customer_email)),9,instr(lower(trim(customer_email)),'@')-9) AS INTEGER)) clean_customer,coalesce(trim(category),CASE substr(clean_sku,5,2) WHEN 'BK' THEN 'Books' WHEN 'EL' THEN 'Electronics' WHEN 'HK' THEN 'Home & Kitchen' WHEN 'FA' THEN 'Fashion' WHEN 'SP' THEN 'Sports' WHEN 'BE' THEN 'Beauty' END) clean_category FROM n WHERE copy=1 AND qty>0 AND unit_price>0 AND unit_price<100000)
INSERT INTO orders_clean SELECT row_hash,trim(order_id),clean_customer,lower(trim(customer_email)),clean_ts,lower(trim(status)),lower(trim(channel)),clean_sku,trim(product_name),clean_category,qty,round(unit_price,2),upper(trim(currency)),upper(trim(country)),date(fx_reference_date) FROM v WHERE clean_customer IS NOT NULL AND clean_category IS NOT NULL AND clean_ts IS NOT NULL ON CONFLICT(order_line_key) DO UPDATE SET customer_id=excluded.customer_id,customer_email=excluded.customer_email,order_ts=excluded.order_ts,status=excluded.status,channel=excluded.channel,product_name=excluded.product_name,category=excluded.category,qty=excluded.qty,unit_price=excluded.unit_price,currency=excluded.currency,country=excluded.country,fx_reference_date=excluded.fx_reference_date;
